void *memcpy(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;

    if (((unsigned long)d & 3) == 0 && ((unsigned long)s & 3) == 0) {
        unsigned int *d4 = (unsigned int *)d;
        const unsigned int *s4 = (const unsigned int *)s;
        while (n >= 16) {
            d4[0] = s4[0]; d4[1] = s4[1]; d4[2] = s4[2]; d4[3] = s4[3];
            d4 += 4; s4 += 4; n -= 16;
        }
        while (n >= 4) {
            *d4++ = *s4++;
            n -= 4;
        }
        d = (unsigned char *)d4;
        s = (const unsigned char *)s4;
    }
    while (n--)
        *d++ = *s++;
    return dst;
}

void *memmove(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;

    if (d == s || n == 0)
        return dst;
    if (d < s)
        return memcpy(dst, src, n);
    d += n;
    s += n;
    while (n--)
        *--d = *--s;
    return dst;
}

void *memset(void *dst, int c, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    unsigned char v = (unsigned char)c;

    while (n && ((unsigned long)d & 3)) {
        *d++ = v;
        n--;
    }
    if (n >= 4) {
        unsigned int w = ((unsigned int)v << 24) | ((unsigned int)v << 16) |
                         ((unsigned int)v << 8) | (unsigned int)v;
        unsigned int *d4 = (unsigned int *)d;
        while (n >= 16) {
            d4[0] = w; d4[1] = w; d4[2] = w; d4[3] = w;
            d4 += 4; n -= 16;
        }
        while (n >= 4) {
            *d4++ = w;
            n -= 4;
        }
        d = (unsigned char *)d4;
    }
    while (n--)
        *d++ = v;
    return dst;
}

int memcmp(const void *a, const void *b, size_t n)
{
    const unsigned char *p = (const unsigned char *)a;
    const unsigned char *q = (const unsigned char *)b;

    while (n--) {
        if (*p != *q)
            return (int)*p - (int)*q;
        p++; q++;
