/* ------------------------------------------------------------------ *
 * Heap.  Lives in .bss, which the VM leaves at zero (unmapped memory
 * reads back as 0), so it costs nothing in the ELF image.
 * ------------------------------------------------------------------ */

#define HEAP_SIZE (40u * 1024u * 1024u)
#define ALIGN_UP(x, a) (((x) + ((a) - 1)) & ~((a) - 1))

static unsigned char heap_area[HEAP_SIZE] __attribute__((aligned(16)));

typedef struct block {
    struct block *next;
    struct block *prev;
    unsigned int size;   /* payload bytes */
    unsigned int used;
} block_t;

#define HDR_SIZE ((unsigned int)ALIGN_UP(sizeof(block_t), 8))

static block_t *heap_head;

static void heap_init(void)
{
    heap_head = (block_t *)heap_area;
    heap_head->next = NULL;
    heap_head->prev = NULL;
    heap_head->size = HEAP_SIZE - HDR_SIZE;
    heap_head->used = 0;
}

void *malloc(size_t size)
{
    block_t *b;
    unsigned int need;

    if (heap_head == NULL)
        heap_init();
    if (size == 0)
        size = 1;
    need = (unsigned int)ALIGN_UP(size, 8);

    for (b = heap_head; b != NULL; b = b->next) {
        if (b->used || b->size < need)
            continue;
        if (b->size >= need + HDR_SIZE + 32) {
            /* split */
            block_t *n = (block_t *)((unsigned char *)b + HDR_SIZE + need);
            n->size = b->size - need - HDR_SIZE;
            n->used = 0;
            n->next = b->next;
            n->prev = b;
            if (b->next)
                b->next->prev = n;
            b->next = n;
            b->size = need;
        }
        b->used = 1;
        return (void *)((unsigned char *)b + HDR_SIZE);
    }
    return NULL;
}

void free(void *ptr)
{
    block_t *b;

    if (ptr == NULL)
        return;
    b = (block_t *)((unsigned char *)ptr - HDR_SIZE);
    b->used = 0;

    /* coalesce forward */
    while (b->next && !b->next->used) {
        block_t *n = b->next;
        b->size += n->size + HDR_SIZE;
        b->next = n->next;
        if (n->next)
            n->next->prev = b;
    }
    /* coalesce backward */
    while (b->prev && !b->prev->used) {
        block_t *p = b->prev;
        p->size += b->size + HDR_SIZE;
        p->next = b->next;
        if (b->next)
            b->next->prev = p;
        b = p;
    }
}

void *calloc(size_t nmemb, size_t size)
{
    size_t n = nmemb * size;
    void *p = malloc(n);
    if (p)
        memset(p, 0, n);
    return p;
}

void *realloc(void *ptr, size_t size)
{
    block_t *b;
    void *p;

    if (ptr == NULL)
        return malloc(size);
    if (size == 0) {
        free(ptr);
        return NULL;
    }
    b = (block_t *)((unsigned char *)ptr - HDR_SIZE);
    if (b->size >= size)
        return ptr;
    p = malloc(size);
    if (p == NULL)
        return NULL;
    memcpy(p, ptr, b->size);
    free(ptr);
    return p;
}

