#define MAX_ATEXIT 8
static void (*atexit_fns[MAX_ATEXIT])(void);
static int atexit_count;

int atexit(void (*fn)(void))
{
    if (atexit_count >= MAX_ATEXIT)
        return -1;
    atexit_fns[atexit_count++] = fn;
    return 0;
}

void __stdio_shutdown(void);

void exit(int status)
{
    int i;

    (void)status;
    for (i = atexit_count - 1; i >= 0; i--)
        atexit_fns[i]();
    __stdio_shutdown();

    /* Returning to address 0 stops the VM's fetch loop cleanly. */
    for (;;)
        __asm__ __volatile__("jr $zero\n\tnop");
}

void abort(void)
{
    exit(1);
}

