double strtod(const char *s, char **endp)
{
    const char *p = s;
    int neg = 0, any = 0;
    double val = 0.0;

    while (isspace((unsigned char)*p))
        p++;
    if (*p == '+' || *p == '-')
        neg = (*p++ == '-');
    while (isdigit((unsigned char)*p)) {
        val = val * 10.0 + (double)(*p - '0');
        p++;
        any = 1;
    }
    if (*p == '.') {
        double scale = 0.1;
        p++;
        while (isdigit((unsigned char)*p)) {
            val += scale * (double)(*p - '0');
            scale *= 0.1;
            p++;
            any = 1;
        }
    }
    if (any && (*p == 'e' || *p == 'E')) {
        const char *q = p + 1;
        int eneg = 0, e = 0, edig = 0;
        if (*q == '+' || *q == '-')
            eneg = (*q++ == '-');
        while (isdigit((unsigned char)*q)) {
            e = e * 10 + (*q - '0');
            q++;
            edig = 1;
        }
        if (edig) {
            double f = 1.0;
            int i;
            for (i = 0; i < e; i++)
                f *= 10.0;
            if (eneg)
                val /= f;
            else
                val *= f;
            p = q;
        }
    }
    if (endp)
        *endp = (char *)(any ? p : s);
    return neg ? -val : val;
}

