#define MAX_FILES 24

static FILE files[MAX_FILES];
static FILE std_files[3];

FILE *stdin = &std_files[0];
FILE *stdout = &std_files[1];
FILE *stderr = &std_files[2];

static int std_inited;

static void std_init(void)
{
    int i;
    if (std_inited)
        return;
    std_inited = 1;
    for (i = 0; i < 3; i++) {
        std_files[i].fd = i;
        std_files[i].ungot = -1;
        std_files[i].pos = 0;
        std_files[i].bufpos = 0;
        std_files[i].buflen = 0;
    }
    std_files[0].flags = F_READ | F_OPEN;
    std_files[1].flags = F_WRITE | F_OPEN;
    std_files[2].flags = F_WRITE | F_OPEN;
}

/* Drop any read-ahead and put the kernel file offset back where the
 * caller thinks it is. */
static void drop_readahead(FILE *f)
{
    if (f->buflen > f->bufpos)
        __sys_lseek(f->fd, f->pos, SEEK_SET);
    f->bufpos = 0;
    f->buflen = 0;
    f->ungot = -1;
}

FILE *fopen(const char *path, const char *mode)
{
    int i, flags = 0;
    unsigned int ff = 0;
    long fd;
    FILE *f = NULL;

    std_init();

    switch (mode[0]) {
    case 'r':
        if (strchr(mode, '+')) {
            flags = O_RDWR;
            ff = F_READ | F_WRITE;
        } else {
            flags = O_RDONLY;
            ff = F_READ;
        }
        break;
    case 'w':
        flags = O_WRONLY | O_CREAT | O_TRUNC;
        ff = F_WRITE;
        break;
    case 'a':
        flags = O_WRONLY | O_CREAT | O_APPEND;
        ff = F_WRITE | F_APPEND;
        break;
    default:
        return NULL;
    }

    for (i = 0; i < MAX_FILES; i++) {
        if (!(files[i].flags & F_OPEN)) {
            f = &files[i];
            break;
        }
    }
    if (f == NULL)
        return NULL;

    fd = __sys_open(path, flags, 0666);
    if (fd < 0) {
        errno = ENOENT;
        return NULL;
    }

    f->fd = (int)fd;
    f->flags = ff | F_OPEN;
    f->pos = 0;
    f->bufpos = 0;
    f->buflen = 0;
    f->ungot = -1;
    return f;
}

FILE *freopen(const char *path, const char *mode, FILE *f)
{
    if (f)
        fclose(f);
    return fopen(path, mode);
}

int fclose(FILE *f)
{
    if (f == NULL || !(f->flags & F_OPEN))
        return EOF;
    if (f->fd > 2)
        __sys_close(f->fd);
    f->flags = 0;
    f->bufpos = f->buflen = 0;
    f->ungot = -1;
    return 0;
}

/* Called from exit(): the VM only commits written data to the host file
 * system when a descriptor is closed, so every open stream must be closed. */
void __stdio_shutdown(void)
{
    int i;
    for (i = 0; i < MAX_FILES; i++)
        if (files[i].flags & F_OPEN)
            fclose(&files[i]);
}

static int refill(FILE *f)
{
    long n;

    if (!(f->flags & F_READ)) {
        f->flags |= F_ERR;
        return -1;
    }
    f->bufpos = 0;
    f->buflen = 0;
    n = __sys_read(f->fd, f->buf, FBUF_SIZE);
    if (n <= 0) {
        if (n < 0)
            f->flags |= F_ERR;
        else
            f->flags |= F_EOF;
        return -1;
    }
    f->buflen = (int)n;
    return 0;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f)
{
    unsigned char *p = (unsigned char *)ptr;
    size_t total, done = 0;

    if (f == NULL || !(f->flags & F_READ) || size == 0 || nmemb == 0)
        return 0;
    total = size * nmemb;

    if (f->ungot >= 0 && total > 0) {
        *p++ = (unsigned char)f->ungot;
        f->ungot = -1;
        f->pos++;
        done++;
    }

    while (done < total) {
        size_t avail = (size_t)(f->buflen - f->bufpos);
        if (avail > 0) {
            size_t n = total - done;
            if (n > avail)
                n = avail;
            memcpy(p, f->buf + f->bufpos, n);
            f->bufpos += (int)n;
            f->pos += (long)n;
            p += n;
            done += n;
            continue;
        }
        if (total - done >= FBUF_SIZE) {
            long n = __sys_read(f->fd, p, total - done);
            if (n <= 0) {
                f->flags |= (n < 0) ? F_ERR : F_EOF;
                break;
            }
            p += n;
            done += (size_t)n;
            f->pos += n;
            continue;
        }
        if (refill(f) < 0)
            break;
    }
    return done / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f)
{
    size_t total;
    long n;

    if (f == NULL || !(f->flags & F_WRITE) || size == 0 || nmemb == 0)
        return 0;
    total = size * nmemb;
    drop_readahead(f);
    n = __sys_write(f->fd, ptr, total);
    if (n < 0) {
        f->flags |= F_ERR;
        return 0;
    }
    f->pos += n;
    return (size_t)n / size;
}

int fseek(FILE *f, long offset, int whence)
{
    long r;

    if (f == NULL)
        return -1;
    if (whence == SEEK_CUR && (f->buflen > f->bufpos || f->ungot >= 0)) {
        offset += f->pos;
        whence = SEEK_SET;
    }
    f->bufpos = f->buflen = 0;
    f->ungot = -1;
    r = __sys_lseek(f->fd, offset, whence);
    if (r < 0)
        return -1;
    f->pos = r;
    f->flags &= ~F_EOF;
    return 0;
}

long ftell(FILE *f)
{
    if (f == NULL)
        return -1;
    return f->pos - (f->ungot >= 0 ? 1 : 0);
}

void rewind(FILE *f)
{
    fseek(f, 0, SEEK_SET);
    if (f)
        f->flags &= ~(F_EOF | F_ERR);
}

int fgetc(FILE *f)
{
    if (f == NULL || !(f->flags & F_READ))
        return EOF;
    if (f->ungot >= 0) {
        int c = f->ungot;
        f->ungot = -1;
        f->pos++;
        return c;
    }
    if (f->bufpos >= f->buflen && refill(f) < 0)
        return EOF;
    f->pos++;
    return (int)f->buf[f->bufpos++];
}

int getc(FILE *f)
{
    return fgetc(f);
}

int getchar(void)
{
    return fgetc(stdin);
}

int ungetc(int c, FILE *f)
{
    if (f == NULL || c == EOF)
        return EOF;
    f->ungot = c & 0xFF;
    f->pos--;
    f->flags &= ~F_EOF;
    return c & 0xFF;
}

char *fgets(char *s, int size, FILE *f)
{
    int i = 0, c;

    if (size <= 0)
        return NULL;
    while (i < size - 1) {
        c = fgetc(f);
        if (c == EOF)
            break;
        s[i++] = (char)c;
        if (c == '\n')
            break;
    }
    if (i == 0)
        return NULL;
    s[i] = 0;
    return s;
}

int fputc(int c, FILE *f)
{
    unsigned char ch = (unsigned char)c;

    std_init();
    if (f == NULL || !(f->flags & F_WRITE))
        return EOF;
    drop_readahead(f);
    if (__sys_write(f->fd, &ch, 1) != 1) {
        f->flags |= F_ERR;
        return EOF;
    }
    f->pos++;
    return (int)ch;
}

int putc(int c, FILE *f)
{
    return fputc(c, f);
}

int putchar(int c)
{
    std_init();
    return fputc(c, stdout);
}

int fputs(const char *s, FILE *f)
{
    size_t n = strlen(s);

    std_init();
    if (f == NULL || !(f->flags & F_WRITE))
        return EOF;
    drop_readahead(f);
    if (n && __sys_write(f->fd, s, n) < 0) {
        f->flags |= F_ERR;
        return EOF;
    }
    f->pos += (long)n;
    return 0;
}

int puts(const char *s)
{
    std_init();
    if (fputs(s, stdout) == EOF)
        return EOF;
    return fputc('\n', stdout) == EOF ? EOF : 0;
}

int feof(FILE *f)
{
    return f && (f->flags & F_EOF) ? 1 : 0;
}

int ferror(FILE *f)
{
    return f && (f->flags & F_ERR) ? 1 : 0;
}

void clearerr(FILE *f)
{
    if (f)
        f->flags &= ~(F_EOF | F_ERR);
}

int fflush(FILE *f)
{
    (void)f;   /* writes are unbuffered */
    return 0;
}

int fileno(FILE *f)
{
    return f ? f->fd : -1;
}

void setbuf(FILE *f, char *buf)
{
    (void)f; (void)buf;
}

int setvbuf(FILE *f, char *buf, int mode, size_t size)
{
    (void)f; (void)buf; (void)mode; (void)size;
    return 0;
}

void perror(const char *s)
{
    std_init();
    if (s && *s) {
        fputs(s, stderr);
        fputs(": ", stderr);
    }
    fputs(strerror(errno), stderr);
    fputc('\n', stderr);
}

#include "stdio_impl.h"
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdarg.h>

/* ------------------------------------------------------------------ *
 * Number helpers
 * ------------------------------------------------------------------ */

static int utoa_base(unsigned long long v, char *out, int base, int upper)
{
    static const char *ld = "0123456789abcdef";
    static const char *ud = "0123456789ABCDEF";
    const char *digits = upper ? ud : ld;
    char tmp[24];
    int n = 0, i;

    if (v == 0)
        tmp[n++] = '0';
    while (v) {
        tmp[n++] = digits[v % (unsigned)base];
        v /= (unsigned)base;
    }
    for (i = 0; i < n; i++)
        out[i] = tmp[n - 1 - i];
    out[n] = 0;
    return n;
}

static double pow10i(int e)
{
    double r = 1.0;
    int i;

    if (e < 0) {
        for (i = 0; i < -e; i++)
            r /= 10.0;
    } else {
        for (i = 0; i < e; i++)
            r *= 10.0;
    }
    return r;
}

/* %f style conversion; returns length written to out (NUL terminated) */
static int dtoa_fixed(char *out, double v, int prec, int plus, int space)
{
    int n = 0, i;
    double ip, fp;
    char digits[32];
    int ndig;

    if (__isnan(v)) {
        strcpy(out, "nan");
        return 3;
    }
    if (v < 0.0) {
        out[n++] = '-';
        v = -v;
    } else if (plus) {
        out[n++] = '+';
    } else if (space) {
        out[n++] = ' ';
    }
    if (__isinf(v)) {
        strcpy(out + n, "inf");
        return n + 3;
    }

    v += 0.5 * pow10i(-prec);

    ip = floor(v);
    fp = v - ip;

    /* integer part */
    ndig = 0;
    if (ip < 1.0) {
        digits[ndig++] = '0';
    } else {
        while (ip >= 1.0 && ndig < 30) {
            double q = floor(ip / 10.0);
            int d = (int)(ip - q * 10.0);
            if (d < 0) d = 0;
            if (d > 9) d = 9;
            digits[ndig++] = (char)('0' + d);
            ip = q;
        }
    }
    for (i = ndig - 1; i >= 0; i--)
        out[n++] = digits[i];

    if (prec > 0) {
        out[n++] = '.';
        for (i = 0; i < prec; i++) {
            int d;
            fp *= 10.0;
            d = (int)fp;
            if (d < 0) d = 0;
            if (d > 9) d = 9;
            out[n++] = (char)('0' + d);
            fp -= (double)d;
        }
    }
    out[n] = 0;
    return n;
}

static int dtoa_exp(char *out, double v, int prec, int upper, int plus,
                    int space)
{
    int n = 0, e = 0, i;
    char mant[64];
    char ebuf[8];
    int elen;

    if (__isnan(v)) {
        strcpy(out, "nan");
        return 3;
    }
    if (v < 0.0) {
        out[n++] = '-';
        v = -v;
    } else if (plus) {
        out[n++] = '+';
    } else if (space) {
        out[n++] = ' ';
    }
    if (__isinf(v)) {
        strcpy(out + n, "inf");
        return n + 3;
    }
    if (v != 0.0) {
        while (v >= 10.0) {
            v /= 10.0;
            e++;
        }
        while (v < 1.0) {
            v *= 10.0;
            e--;
        }
    }
    i = dtoa_fixed(mant, v, prec, 0, 0);
    /* rounding may have produced "10.xxx" */
    if (mant[0] == '1' && mant[1] == '0' && (prec == 0 || mant[2] == '.')) {
        e++;
        i = dtoa_fixed(mant, v / 10.0, prec, 0, 0);
    }
    memcpy(out + n, mant, (size_t)i);
    n += i;
    out[n++] = upper ? 'E' : 'e';
    out[n++] = (e < 0) ? '-' : '+';
    if (e < 0)
        e = -e;
    elen = utoa_base((unsigned long long)e, ebuf, 10, 0);
    if (elen < 2) {
        out[n++] = '0';
    }
    memcpy(out + n, ebuf, (size_t)elen);
    n += elen;
    out[n] = 0;
    return n;
}

/* ------------------------------------------------------------------ *
 * Core formatter
 * ------------------------------------------------------------------ */

int __vfmt_out(void (*emit)(void *, const char *, size_t), void *arg,
               const char *fmt, va_list ap)
{
    int total = 0;
    char numbuf[400];

    while (*fmt) {
        const char *start = fmt;
        int leftalign = 0, zeropad = 0, plus = 0, space = 0, alt = 0;
        int width = 0, prec = -1, lmod = 0;
        int base = 10, is_signed = 0, upper = 0;
        const char *prefix = "";
        char conv;
        const char *body;
        int blen, padlen;
        char sign = 0;

        if (*fmt != '%') {
            while (*fmt && *fmt != '%')
                fmt++;
            emit(arg, start, (size_t)(fmt - start));
            total += (int)(fmt - start);
            continue;
        }
        fmt++;
        if (*fmt == '%') {
            emit(arg, "%", 1);
            total++;
            fmt++;
            continue;
        }

        for (;;) {
            if (*fmt == '-') { leftalign = 1; fmt++; }
            else if (*fmt == '0') { zeropad = 1; fmt++; }
            else if (*fmt == '+') { plus = 1; fmt++; }
            else if (*fmt == ' ') { space = 1; fmt++; }
            else if (*fmt == '#') { alt = 1; fmt++; }
            else break;
        }
        if (*fmt == '*') {
            width = va_arg(ap, int);
            if (width < 0) {
                leftalign = 1;
                width = -width;
            }
            fmt++;
        } else {
            while (*fmt >= '0' && *fmt <= '9')
                width = width * 10 + (*fmt++ - '0');
        }
        if (*fmt == '.') {
            fmt++;
            prec = 0;
            if (*fmt == '*') {
                prec = va_arg(ap, int);
                fmt++;
            } else {
                while (*fmt >= '0' && *fmt <= '9')
                    prec = prec * 10 + (*fmt++ - '0');
            }
            if (prec < 0)
                prec = -1;
        }
        while (*fmt == 'h') { lmod = 1; fmt++; }
        while (*fmt == 'l') { lmod = (lmod == 3) ? 4 : 3; fmt++; }
        if (*fmt == 'z' || *fmt == 't') { lmod = 3; fmt++; }
        if (*fmt == 'j') { lmod = 4; fmt++; }
        if (*fmt == 'L') { fmt++; }

        conv = *fmt++;
        if (conv == 0)
            break;

        body = numbuf;
        switch (conv) {
        case 'd':
        case 'i':
            is_signed = 1;
            goto integer;
        case 'u':
            goto integer;
        case 'o':
            base = 8;
            goto integer;
        case 'X':
            upper = 1;
            /* fall through */
        case 'x':
            base = 16;
            if (alt)
                prefix = upper ? "0X" : "0x";
            goto integer;
        case 'p': {
            unsigned long pv = (unsigned long)va_arg(ap, void *);
            prefix = "0x";
            base = 16;
            blen = utoa_base((unsigned long long)pv, numbuf, 16, 0);
            break;
        }
        integer: {
            unsigned long long uv;
            if (is_signed) {
                long long sv;
                if (lmod == 4)
                    sv = va_arg(ap, long long);
                else if (lmod == 3)
                    sv = (long long)va_arg(ap, long);
                else
                    sv = (long long)va_arg(ap, int);
                if (sv < 0) {
                    sign = '-';
                    uv = (unsigned long long)(-sv);
                } else {
                    uv = (unsigned long long)sv;
                    if (plus)
                        sign = '+';
                    else if (space)
                        sign = ' ';
                }
            } else {
                if (lmod == 4)
                    uv = va_arg(ap, unsigned long long);
                else if (lmod == 3)
                    uv = (unsigned long long)va_arg(ap, unsigned long);
                else
                    uv = (unsigned long long)va_arg(ap, unsigned int);
            }
            blen = utoa_base(uv, numbuf, base, upper);
            if (prec >= 0 && blen < prec) {
                /* left-pad with zeros to precision */
                int add = prec - blen;
                int i;
                for (i = blen; i >= 0; i--)
                    numbuf[i + add] = numbuf[i];
                for (i = 0; i < add; i++)
                    numbuf[i] = '0';
                blen += add;
            }
            break;
        }
        case 'c': {
            numbuf[0] = (char)va_arg(ap, int);
            numbuf[1] = 0;
            blen = 1;
            break;
        }
        case 's': {
            const char *s = va_arg(ap, const char *);
            if (s == NULL)
                s = "(null)";
            body = s;
            if (prec >= 0)
                blen = (int)strnlen(s, (size_t)prec);
            else
                blen = (int)strlen(s);
            break;
        }
        case 'f':
        case 'F': {
            double dv = va_arg(ap, double);
            blen = dtoa_fixed(numbuf, dv, prec < 0 ? 6 : prec, plus, space);
            break;
        }
        case 'e':
        case 'E': {
            double dv = va_arg(ap, double);
            blen = dtoa_exp(numbuf, dv, prec < 0 ? 6 : prec, conv == 'E', plus,
                            space);
            break;
        }
        case 'g':
        case 'G': {
            double dv = va_arg(ap, double);
            double av = dv < 0 ? -dv : dv;
            int p = (prec < 0) ? 6 : (prec == 0 ? 1 : prec);
            int e = 0;
            if (av != 0.0 && !__isnan(av) && !__isinf(av)) {
                double t = av;
                while (t >= 10.0) { t /= 10.0; e++; }
                while (t < 1.0) { t *= 10.0; e--; }
            }
            if (e < -4 || e >= p)
                blen = dtoa_exp(numbuf, dv, p - 1, conv == 'G', plus, space);
            else
                blen = dtoa_fixed(numbuf, dv, p - 1 - e, plus, space);
            /* strip trailing zeros */
            if (!alt && strchr(numbuf, '.')) {
                char *ep = strchr(numbuf, 'e');
                if (ep == NULL)
                    ep = strchr(numbuf, 'E');
                if (ep == NULL) {
                    while (blen > 0 && numbuf[blen - 1] == '0')
                        blen--;
                    if (blen > 0 && numbuf[blen - 1] == '.')
                        blen--;
                    numbuf[blen] = 0;
                }
            }
            break;
        }
        case 'n': {
            int *np = va_arg(ap, int *);
            if (np)
                *np = total;
            continue;
        }
        default:
            numbuf[0] = conv;
            blen = 1;
            break;
        }

        {
            int plen = (int)strlen(prefix);
            int slen = sign ? 1 : 0;
            padlen = width - blen - plen - slen;
            if (padlen < 0)
                padlen = 0;

            if (!leftalign && !zeropad) {
                while (padlen-- > 0) {
                    emit(arg, " ", 1);
                    total++;
                }
                padlen = 0;
            }
            if (sign) {
                emit(arg, &sign, 1);
                total++;
            }
            if (plen) {
                emit(arg, prefix, (size_t)plen);
                total += plen;
            }
            if (!leftalign && zeropad) {
                while (padlen-- > 0) {
                    emit(arg, "0", 1);
                    total++;
                }
                padlen = 0;
            }
            emit(arg, body, (size_t)blen);
            total += blen;
            while (padlen-- > 0) {
                emit(arg, " ", 1);
                total++;
            }
        }
    }
    return total;
}

/* ------------------------------------------------------------------ *
 * Sinks
 * ------------------------------------------------------------------ */

typedef struct {
    char *buf;
    size_t cap;   /* including NUL slot; 0 means "no store" */
    size_t len;   /* characters that would have been written */
} strsink;

static void emit_str(void *a, const char *s, size_t n)
{
    strsink *ss = (strsink *)a;
    size_t i;

    for (i = 0; i < n; i++) {
        if (ss->cap > 0 && ss->len + 1 < ss->cap)
            ss->buf[ss->len] = s[i];
        ss->len++;
    }
}

typedef struct {
    FILE *f;
    char buf[256];
    size_t len;
} filesink;

static void filesink_flush(filesink *fs)
{
    if (fs->len) {
        fwrite(fs->buf, 1, fs->len, fs->f);
        fs->len = 0;
    }
}

static void emit_file(void *a, const char *s, size_t n)
{
    filesink *fs = (filesink *)a;
    size_t i;

    for (i = 0; i < n; i++) {
        fs->buf[fs->len++] = s[i];
        if (fs->len == sizeof(fs->buf))
            filesink_flush(fs);
    }
}

int vsnprintf(char *s, size_t n, const char *fmt, va_list ap)
{
    strsink ss;
    int r;

    ss.buf = s;
    ss.cap = n;
    ss.len = 0;
    r = __vfmt_out(emit_str, &ss, fmt, ap);
    if (n > 0)
        s[(ss.len < n - 1) ? ss.len : n - 1] = 0;
    return r;
}

int vsprintf(char *s, const char *fmt, va_list ap)
{
    return vsnprintf(s, (size_t)0x7FFFFFFF, fmt, ap);
}

int snprintf(char *s, size_t n, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsnprintf(s, n, fmt, ap);
    va_end(ap);
    return r;
}

int sprintf(char *s, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsprintf(s, fmt, ap);
    va_end(ap);
    return r;
}

int vfprintf(FILE *f, const char *fmt, va_list ap)
{
    filesink fs;
    int r;

    fs.f = f;
    fs.len = 0;
    r = __vfmt_out(emit_file, &fs, fmt, ap);
    filesink_flush(&fs);
    return r;
}

int fprintf(FILE *f, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}

int vprintf(const char *fmt, va_list ap)
{
    return vfprintf(stdout, fmt, ap);
}

int printf(const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}

#include "stdio_impl.h"
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include <math.h>
#include <stdarg.h>

typedef struct {
    const char *s;      /* string source (NULL for FILE) */
    size_t pos;
    FILE *f;
    int pushback;
    int nread;
} scansrc;

static int src_get(scansrc *sc)
{
    int c;

    if (sc->pushback >= 0) {
        c = sc->pushback;
        sc->pushback = -1;
        sc->nread++;
        return c;
    }
    if (sc->s) {
        c = (unsigned char)sc->s[sc->pos];
        if (c == 0)
            return EOF;
        sc->pos++;
    } else {
        c = fgetc(sc->f);
        if (c == EOF)
            return EOF;
    }
    sc->nread++;
    return c;
}

static void src_unget(scansrc *sc, int c)
{
    if (c == EOF)
        return;
    sc->pushback = c;
    sc->nread--;
}

static int vscan(scansrc *sc, const char *fmt, va_list ap)
{
    int assigned = 0;
    int c;

    while (*fmt) {
        if (isspace((unsigned char)*fmt)) {
            do {
                c = src_get(sc);
            } while (c != EOF && isspace(c));
            src_unget(sc, c);
            fmt++;
            continue;
        }
        if (*fmt != '%') {
            c = src_get(sc);
            if (c != (unsigned char)*fmt) {
                src_unget(sc, c);
                return assigned;
            }
            fmt++;
            continue;
        }

        fmt++;
        {
            int suppress = 0, width = 0, lmod = 0;
            char conv;

            if (*fmt == '*') {
                suppress = 1;
                fmt++;
            }
            while (*fmt >= '0' && *fmt <= '9')
                width = width * 10 + (*fmt++ - '0');
            while (*fmt == 'h') { lmod = 1; fmt++; }
            while (*fmt == 'l') { lmod = (lmod == 3) ? 4 : 3; fmt++; }
            if (*fmt == 'L' || *fmt == 'z' || *fmt == 'j') { lmod = 3; fmt++; }

            conv = *fmt++;
            if (conv == 0)
                break;

            if (conv == '%') {
                c = src_get(sc);
                if (c != '%') {
                    src_unget(sc, c);
                    return assigned;
                }
                continue;
            }

            if (conv == 'c') {
                int n = width ? width : 1;
                char *out = suppress ? NULL : va_arg(ap, char *);
                int got = 0;
                while (got < n) {
                    c = src_get(sc);
                    if (c == EOF)
                        break;
                    if (out)
                        out[got] = (char)c;
                    got++;
                }
                if (got == 0)
                    return assigned ? assigned : EOF;
                if (out)
                    assigned++;
                continue;
            }

            if (conv == 's') {
                char *out = suppress ? NULL : va_arg(ap, char *);
                int got = 0;
                do {
                    c = src_get(sc);
                } while (c != EOF && isspace(c));
                if (c == EOF)
                    return assigned ? assigned : EOF;
                while (c != EOF && !isspace(c) &&
                       (width == 0 || got < width)) {
                    if (out)
                        out[got] = (char)c;
                    got++;
                    c = src_get(sc);
                }
                src_unget(sc, c);
                if (out) {
                    out[got] = 0;
                    assigned++;
                }
                continue;
            }

            if (conv == '[') {
                unsigned char set[256];
                int negate = 0, got = 0;
                char *out = suppress ? NULL : va_arg(ap, char *);

                memset(set, 0, sizeof(set));
                if (*fmt == '^') {
                    negate = 1;
                    fmt++;
                }
                if (*fmt == ']') {
                    set[(unsigned char)']'] = 1;
                    fmt++;
                }
                while (*fmt && *fmt != ']') {
                    if (fmt[1] == '-' && fmt[2] && fmt[2] != ']') {
                        unsigned char lo = (unsigned char)fmt[0];
                        unsigned char hi = (unsigned char)fmt[2];
                        unsigned int i;
                        for (i = lo; i <= hi; i++)
                            set[i] = 1;
                        fmt += 3;
                    } else {
                        set[(unsigned char)*fmt] = 1;
                        fmt++;
                    }
                }
                if (*fmt == ']')
                    fmt++;

                for (;;) {
                    c = src_get(sc);
                    if (c == EOF)
                        break;
                    if ((set[c] ? 1 : 0) == negate) {
                        src_unget(sc, c);
                        break;
                    }
                    if (width && got >= width) {
                        src_unget(sc, c);
                        break;
                    }
                    if (out)
                        out[got] = (char)c;
                    got++;
                }
                if (got == 0)
                    return assigned ? assigned : EOF;
                if (out) {
                    out[got] = 0;
                    assigned++;
                }
                continue;
            }

            /* numeric conversions */
            {
                char tok[64];
                int n = 0;
                int base = 10;
                int isfloat = 0;

                do {
                    c = src_get(sc);
                } while (c != EOF && isspace(c));

                if (conv == 'x' || conv == 'X')
                    base = 16;
                else if (conv == 'o')
                    base = 8;
                else if (conv == 'i')
                    base = 0;
                else if (conv == 'f' || conv == 'e' || conv == 'g' ||
                         conv == 'F' || conv == 'E' || conv == 'G')
                    isfloat = 1;

                if (c == '+' || c == '-') {
                    tok[n++] = (char)c;
                    c = src_get(sc);
                }
                if (!isfloat && (base == 16 || base == 0) && c == '0') {
                    tok[n++] = (char)c;
                    c = src_get(sc);
                    if (c == 'x' || c == 'X') {
                        tok[n++] = (char)c;
                        c = src_get(sc);
                        base = 16;
                    } else if (base == 0) {
                        base = 8;
                    }
                }
                for (;;) {
                    int ok;
                    if (c == EOF || n >= (int)sizeof(tok) - 1)
                        break;
                    if (width && n >= width)
                        break;
                    if (isfloat)
                        ok = isdigit(c) || c == '.' || c == 'e' || c == 'E' ||
                             ((c == '+' || c == '-') && n > 0 &&
                              (tok[n - 1] == 'e' || tok[n - 1] == 'E'));
                    else if (base == 16)
                        ok = isxdigit(c);
                    else if (base == 8)
                        ok = (c >= '0' && c <= '7');
                    else
                        ok = isdigit(c);
                    if (!ok)
                        break;
                    tok[n++] = (char)c;
                    c = src_get(sc);
                }
                src_unget(sc, c);
                tok[n] = 0;
                if (n == 0 || (n == 1 && (tok[0] == '+' || tok[0] == '-')))
                    return assigned ? assigned : EOF;

                if (suppress)
                    continue;

                if (isfloat) {
                    double d = strtod(tok, NULL);
                    if (lmod >= 3)
                        *va_arg(ap, double *) = d;
                    else
                        *va_arg(ap, float *) = (float)d;
                } else if (conv == 'u') {
                    unsigned long v = strtoul(tok, NULL, base);
                    if (lmod == 1)
                        *va_arg(ap, unsigned short *) = (unsigned short)v;
                    else
                        *va_arg(ap, unsigned int *) = (unsigned int)v;
                } else {
                    long v = strtol(tok, NULL, base);
                    if (lmod == 1)
                        *va_arg(ap, short *) = (short)v;
                    else
                        *va_arg(ap, int *) = (int)v;
                }
                assigned++;
            }
        }
    }
    return assigned;
}

int vsscanf(const char *s, const char *fmt, va_list ap)
{
    scansrc sc;

    sc.s = s;
    sc.pos = 0;
    sc.f = NULL;
    sc.pushback = -1;
    sc.nread = 0;
    return vscan(&sc, fmt, ap);
}

int vfscanf(FILE *f, const char *fmt, va_list ap)
{
    scansrc sc;

    sc.s = NULL;
    sc.pos = 0;
    sc.f = f;
    sc.pushback = -1;
    sc.nread = 0;
    return vscan(&sc, fmt, ap);
}

int sscanf(const char *s, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsscanf(s, fmt, ap);
    va_end(ap);
    return r;
}

int fscanf(FILE *f, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfscanf(f, fmt, ap);
    va_end(ap);
    return r;
}

int scanf(const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfscanf(stdin, fmt, ap);
    va_end(ap);
    return r;
}
